/**
 * Normalisasi string nama perusahaan:
 * Menghapus prefix PT, CV, tanda baca, dan spasi untuk pencocokan akurat.
 */
export function normalisasiNama(input: string): string {
  return input
    .toUpperCase()
    .replace(/\b(PT|CV|PERSERO|INC|LTD|TBK|INDONESIA)\b/gi, "")
    .replace(/[^A-Z0-9]/g, "")
    .trim();
}

/**
 * Pencocokan toleran salah ketik (Exact, Substring, dan Bigram Fuzzy Matching).
 */
export function cocokanP3MI(namaInput: string | null | undefined): HasilPencocokanP3MI {
  if (!namaInput || namaInput.trim() === "") {
    return { keadaan: "TIDAK_DITEMUKAN", tanggalSnapshot: TANGGAL_SNAPSHOT_P3MI };
  }


  const normalizedInput = normalisasiNama(namaInput);
  if (normalizedInput.length < 3) {
    return { keadaan: "TIDAK_DITEMUKAN", tanggalSnapshot: TANGGAL_SNAPSHOT_P3MI };
  }

  // 1. Exact Match
  for (const item of DAFTAR_P3MI) {
    if (normalisasiNama(item.nama) === normalizedInput) {
      return {
        keadaan: "DITEMUKAN",
        tanggalSnapshot: TANGGAL_SNAPSHOT_P3MI,
        target: item,
        skorKemiripan: 1.0
      };
    }
  }

  // 2. Substring Match
  for (const item of DAFTAR_P3MI) {
    const normNama = normalisasiNama(item.nama);
    if (normNama.includes(normalizedInput) || normalizedInput.includes(normNama)) {
      return {
        keadaan: "MIRIP",
        tanggalSnapshot: TANGGAL_SNAPSHOT_P3MI,
        target: item,
        skorKemiripan: 0.85
      };
    }
  }

  // 3. Bigram Dice Coefficient untuk typo/saltik
  function getBigrams(str: string): Set<string> {
    const bigrams = new Set<string>();
    for (let i = 0; i < str.length - 1; i++) {
      bigrams.add(str.slice(i, i + 2));
    }
    return bigrams;
  }

  const inputBigrams = getBigrams(normalizedInput);
  let bestMatch: P3MICompany | undefined;
  let bestScore = 0;

  for (const item of DAFTAR_P3MI) {
    const normNama = normalisasiNama(item.nama);
    const targetBigrams = getBigrams(normNama);
    
    let intersection = 0;
    for (const bg of inputBigrams) {
      if (targetBigrams.has(bg)) intersection++;
    }

    const total = inputBigrams.size + targetBigrams.size;
    const score = total === 0 ? 0 : (2.0 * intersection) / total;

    if (score > bestScore) {
      bestScore = score;
      bestMatch = item;
    }
  }

  if (bestScore >= 0.78 && bestMatch) {
    return {
      keadaan: "MIRIP",
      tanggalSnapshot: TANGGAL_SNAPSHOT_P3MI,
      target: bestMatch,
      skorKemiripan: bestScore
    };
  }

  return { keadaan: "TIDAK_DITEMUKAN", tanggalSnapshot: TANGGAL_SNAPSHOT_P3MI };
}

export const cariP3MI = cocokanP3MI;

